import glob, os, xlrd, datetime, traceback
from xlrd.xldate import xldate_as_tuple, xldate_as_datetime
found=0
for f in sorted(glob.glob('tests/samples/*.xls')):
    try:
        bk = xlrd.open_workbook(f)
    except Exception as e:
        continue
    for sh in bk.sheets():
        for r in range(sh.nrows):
            for c in range(sh.ncols):
                if sh.cell_type(r,c)==xlrd.XL_CELL_DATE:
                    v=sh.cell_value(r,c)
                    try:
                        t=xldate_as_tuple(v,bk.datemode)
                        dt=datetime.datetime(*t) if t[0] else None
                        d2=xldate_as_datetime(v,bk.datemode)
                        print(os.path.basename(f), sh.name, r,c, v, t, dt, d2)
                    except Exception as e:
                        print("ERR", os.path.basename(f), r,c,v, type(e).__name__, e)
                    found+=1
                    if found>25: raise SystemExit
